const CAT_AGENTES: [string, string][] = Object.entries<any>(PADROES.find(p => p.codigo === 'AGENTES_RISCO')!.valor).flatMap(([t, g]) => g.itens.map((i: any): [string, string] => [i.id, `${t === 'FISICO' ? 'Físico' : t === 'QUIMICO' ? 'Químico' : 'Biológico'} – ${i.agente}`.slice(0, 110)]));
const T = (n: string, l: string, v = ''): Campo => ({ n, l, t: 'txt', v });
const A = (n: string, l: string): Campo => ({ n, l, t: 'area', v: '' });
const parse = (cat: string, id: string, nome: string, desc: string, campos: Campo[], registro: Registro): Ferr =>
  ({ id, cat, nome, desc, campos, tipo: 'registro', registro, calc: () => { throw new ErroCalc('Esta ferramenta é um registro: use os botões Novo/Salvar.'); } });
const R = (cat: string) => (id: string, nome: string, desc: string, campos: Campo[], registro: Registro = { func: true }) => parse(cat, id, nome, desc, campos, registro);

